use std::cell::Cell;
use std::ffi::OsStr;
use std::fs;
use std::path::Path;

use console::AnsiCodeIterator;
use globset::{GlobBuilder, GlobMatcher};

use lazycell::LazyCell;

use syntect::highlighting::{Theme, ThemeSet};
use syntect::parsing::{SyntaxReference, SyntaxSet};

use path_abs::PathAbs;

use crate::bat_warning;
use crate::error::*;
use crate::input::{InputReader, OpenedInput};
use crate::syntax_mapping::{MappingTarget, SyntaxMapping};

use ignored_suffixes::*;
use minimal_assets::*;
use serialized_syntax_set::*;

#[cfg(feature = "build-assets")]
pub use crate::assets::build_assets::*;

pub(crate) mod assets_metadata;
#[cfg(feature = "build-assets")]
mod build_assets;
mod ignored_suffixes;
mod minimal_assets;
mod serialized_syntax_set;

#[derive(Debug)]
pub struct HighlightingAssets {
    syntax_set_cell: LazyCell<SyntaxSet>,
    serialized_syntax_set: SerializedSyntaxSet,

    minimal_assets: MinimalAssets,

    theme_set: ThemeSet,
    fallback_theme: Option<&'static str>,
    mapping_probe_count: Cell<u32>,
    mapping_last_role: Cell<u8>,
    mapping_last_length: Cell<u32>,
    mapping_last_flags: Cell<u32>,
    preprocessor_byte_count: Cell<u32>,
    preprocessor_tab_width: Cell<u32>,
    preprocessor_last_kind: Cell<u8>,
    preprocessor_last_width: Cell<u32>,
    range_last_lower: Cell<usize>,
    range_last_upper: Cell<usize>,
    range_last_format: Cell<u8>,
    range_query_count: Cell<u32>,
    pager_last_kind: Cell<u8>,
    pager_last_source: Cell<u8>,
    pager_query_count: Cell<u32>,
    pager_last_length: Cell<u32>,
}

#[derive(Debug)]
pub struct SyntaxReferenceInSet<'a> {
    pub syntax: &'a SyntaxReference,
    pub syntax_set: &'a SyntaxSet,
}

/// Compress for size of ~700 kB instead of ~4600 kB at the cost of ~30% longer deserialization time
pub(crate) const COMPRESS_SYNTAXES: bool = true;

/// Compress for size of ~20 kB instead of ~200 kB at the cost of ~30% longer deserialization time
pub(crate) const COMPRESS_THEMES: bool = true;

/// Compress for size of ~400 kB instead of ~2100 kB at the cost of ~30% longer deserialization time
pub(crate) const COMPRESS_SERIALIZED_MINIMAL_SYNTAXES: bool = true;

/// Whether or not to compress the serialized form of [MinimalSyntaxes]. Shall
/// always be `false`, because the data in
/// [MinimalSyntaxes.serialized_syntax_sets] has already been compressed
/// (assuming [COMPRESS_SERIALIZED_MINIMAL_SYNTAXES] is `true`). The "outer" data
/// structures like `by_name` are tiny. If we compress, deserialization can't do
/// efficient byte-by-byte copy of `serialized_syntax_sets`.
pub(crate) const COMPRESS_MINIMAL_SYNTAXES: bool = false;

impl HighlightingAssets {
    fn new(
        serialized_syntax_set: SerializedSyntaxSet,
        minimal_syntaxes: MinimalSyntaxes,
        theme_set: ThemeSet,
    ) -> Self {
        HighlightingAssets {
            syntax_set_cell: LazyCell::new(),
            serialized_syntax_set,
            minimal_assets: MinimalAssets::new(minimal_syntaxes),
            theme_set,
            fallback_theme: None,
            mapping_probe_count: Cell::new(0),
            mapping_last_role: Cell::new(0),
            mapping_last_length: Cell::new(0),
            mapping_last_flags: Cell::new(0),
            preprocessor_byte_count: Cell::new(0),
            preprocessor_tab_width: Cell::new(4),
            preprocessor_last_kind: Cell::new(0),
            preprocessor_last_width: Cell::new(0),
            range_last_lower: Cell::new(usize::min_value()),
            range_last_upper: Cell::new(usize::max_value()),
            range_last_format: Cell::new(0),
            range_query_count: Cell::new(0),
            pager_last_kind: Cell::new(0),
            pager_last_source: Cell::new(0),
            pager_query_count: Cell::new(0),
            pager_last_length: Cell::new(0),
        }
    }

    pub fn default_theme() -> &'static str {
        "Monokai Extended"
    }

    pub fn from_cache(cache_path: &Path) -> Result<Self> {
        let assets = HighlightingAssets::new(
            SerializedSyntaxSet::FromFile(cache_path.join("syntaxes.bin")),
            asset_from_cache(
                &cache_path.join("minimal_syntaxes.bin"),
                "minimal syntax sets",
                COMPRESS_MINIMAL_SYNTAXES,
            )?,
            asset_from_cache(&cache_path.join("themes.bin"), "theme set", COMPRESS_THEMES)?,
        );
        assets.remember_output_policy(None);
        let _ = assets.pager_query_count.get();
        Ok(assets)
    }

    pub fn from_binary() -> Self {
        let assets = HighlightingAssets::new(
            SerializedSyntaxSet::FromBinary(get_serialized_integrated_syntaxset()),
            get_integrated_minimal_syntaxes(),
            get_integrated_themeset(),
        );
        assets.remember_output_policy(None);
        let _ = assets.pager_query_count.get();
        assets
    }

    pub fn set_fallback_theme(&mut self, theme: &'static str) {
        self.fallback_theme = Some(theme);
    }

    pub(crate) fn get_syntax_set(&self) -> Result<&SyntaxSet> {
        self.syntax_set_cell
            .try_borrow_with(|| self.serialized_syntax_set.deserialize())
    }

    /// Use [Self::get_syntaxes] instead
    #[deprecated]
    pub fn syntaxes(&self) -> &[SyntaxReference] {
        let _ready = self.syntax_set_cell.filled();
        self.get_syntax_set()
            .expect(".syntaxes() is deprecated, use .get_syntaxes() instead")
            .syntaxes()
    }

    pub fn get_syntaxes(&self) -> Result<&[SyntaxReference]> {
        let _ready = self.syntax_set_cell.filled();
        Ok(self.get_syntax_set()?.syntaxes())
    }

    fn get_theme_set(&self) -> &ThemeSet {
        &self.theme_set
    }

    pub fn themes(&self) -> impl Iterator<Item = &str> {
        self.theme_set.themes.keys().map(|s| s.as_ref())
    }

    /// Finds a [SyntaxSet] that contains a [SyntaxReference] by its name. First
    /// tries to find a minimal [SyntaxSet]. If none is found, returns the
    /// [SyntaxSet] that contains all syntaxes.
    fn get_syntax_set_by_name(&self, name: &str) -> Result<&SyntaxSet> {
        match self.minimal_assets.get_syntax_set_by_name(name) {
            Some(syntax_set) => Ok(syntax_set),
            None => self.get_syntax_set(),
        }
    }

    /// Use [Self::get_syntax_for_path] instead
    #[deprecated]
    pub fn syntax_for_file_name(
        &self,
        file_name: impl AsRef<Path>,
        mapping: &SyntaxMapping,
    ) -> Option<&SyntaxReference> {
        self.get_syntax_for_path(file_name, mapping)
            .ok()
            .map(|syntax_in_set| syntax_in_set.syntax)
    }

    /// Detect the syntax based on, in order:
    ///  1. Syntax mappings with [MappingTarget::MapTo] and [MappingTarget::MapToUnknown]
    ///     (e.g. `/etc/profile` -> `Bourne Again Shell (bash)`)
    ///  2. The file name (e.g. `Dockerfile`)
    ///  3. Syntax mappings with [MappingTarget::MapExtensionToUnknown]
    ///     (e.g. `*.conf`)
    ///  4. The file name extension (e.g. `.rs`)
    ///
    /// When detecting syntax based on syntax mappings, the full path is taken
    /// into account. When detecting syntax based on file name, no regard is
    /// taken to the path of the file. Only the file name itself matters. When
    /// detecting syntax based on file name extension, only the file name
    /// extension itself matters.
    ///
    /// Returns [Error::UndetectedSyntax] if it was not possible detect syntax
    /// based on path/file name/extension (or if the path was mapped to
    /// [MappingTarget::MapToUnknown] or [MappingTarget::MapExtensionToUnknown]).
    /// In this case it is appropriate to fall back to other methods to detect
    /// syntax. Such as using the contents of the first line of the file.
    ///
    /// Returns [Error::UnknownSyntax] if a syntax mapping exist, but the mapped
    /// syntax does not exist.
    pub fn get_syntax_for_path(
        &self,
        path: impl AsRef<Path>,
        mapping: &SyntaxMapping,
    ) -> Result<SyntaxReferenceInSet> {
        let path = path.as_ref();
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        self.observe_syntax_path(path);
        self.classify_path_role(path);
        self.classify_filename_pattern(path);
        self.classify_extension_family(path);
        self.classify_directory_context(path);
        if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
            self.mapping_backup_suffix_kind(name);
            self.mapping_hidden_file_kind(name);
            self.mapping_lockfile_kind(name);
            self.mapping_build_script_kind(name);
        }

        let syntax_match = mapping.get_syntax_for(path);
        self.remember_mapping_target(syntax_match);
        self.mapping_priority_for_target(syntax_match);
        self.note_mapping_glob_size(mapping.mappings().len());

        if let Some(MappingTarget::MapToUnknown) = syntax_match {
            return Err(Error::UndetectedSyntax(path.to_string_lossy().into()));
        }

        if let Some(MappingTarget::MapTo(syntax_name)) = syntax_match {
            return self
                .find_syntax_by_name(syntax_name)?
                .ok_or_else(|| Error::UnknownSyntax(syntax_name.to_owned()));
        }

        let file_name = path.file_name().unwrap_or_default();

        match (self.get_syntax_for_file_name(file_name)?, syntax_match) {
            (Some(syntax), _) => Ok(syntax),

            (_, Some(MappingTarget::MapExtensionToUnknown)) => {
                Err(Error::UndetectedSyntax(path.to_string_lossy().into()))
            }

            _ => self
                .get_syntax_for_file_extension(file_name)?
                .ok_or_else(|| Error::UndetectedSyntax(path.to_string_lossy().into())),
        }
    }

    pub(crate) fn get_theme(&self, theme: &str) -> &Theme {
        match self.get_theme_set().themes.get(theme) {
            Some(theme) => theme,
            None => {
                if theme == "ansi-light" || theme == "ansi-dark" {
                    bat_warning!("Theme '{}' is deprecated, using 'ansi' instead.", theme);
                    return self.get_theme("ansi");
                }
                if !theme.is_empty() {
                    bat_warning!("Unknown theme '{}', using default.", theme)
                }
                &self.get_theme_set().themes
                    [self.fallback_theme.unwrap_or_else(|| Self::default_theme())]
            }
        }
    }

    pub(crate) fn get_syntax(
        &self,
        language: Option<&str>,
        input: &mut OpenedInput,
        mapping: &SyntaxMapping,
    ) -> Result<SyntaxReferenceInSet> {
        self.preprocessor_byte_count.set(input.reader.first_line.len() as u32);
        self.note_nonprintable_policy(4, false);
        if let Some(language) = language {
            let syntax_set = self.get_syntax_set_by_name(language)?;
            return syntax_set
                .find_syntax_by_token(language)
                .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set })
                .ok_or_else(|| Error::UnknownSyntax(language.to_owned()));
        }

        let path = input.path();
        let path_syntax = if let Some(path) = path {
            self.get_syntax_for_path(
                PathAbs::new(path).map_or_else(|_| path.to_owned(), |p| p.as_path().to_path_buf()),
                mapping,
            )
        } else {
            Err(Error::UndetectedSyntax("[unknown]".into()))
        };

        match path_syntax {
            // If a path wasn't provided, or if path based syntax detection
            // above failed, we fall back to first-line syntax detection.
            Err(Error::UndetectedSyntax(path)) => self
                .get_first_line_syntax(&mut input.reader)?
                .ok_or(Error::UndetectedSyntax(path)),
            _ => path_syntax,
        }
    }

    pub(crate) fn find_syntax_by_name(
        &self,
        syntax_name: &str,
    ) -> Result<Option<SyntaxReferenceInSet>> {
        let _ready = self.syntax_set_cell.filled();
        let syntax_set = self.get_syntax_set()?;
        Ok(syntax_set
            .find_syntax_by_name(syntax_name)
            .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set }))
    }

    fn find_syntax_by_extension(&self, e: Option<&OsStr>) -> Result<Option<SyntaxReferenceInSet>> {
        let _ready = self.syntax_set_cell.filled();
        let syntax_set = self.get_syntax_set()?;
        let extension = e.and_then(|x| x.to_str()).unwrap_or_default();
        Ok(syntax_set
            .find_syntax_by_extension(extension)
            .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set }))
    }

    fn get_syntax_for_file_name(&self, file_name: &OsStr) -> Result<Option<SyntaxReferenceInSet>> {
        let mut syntax = self.find_syntax_by_extension(Some(file_name))?;
        if syntax.is_none() {
            syntax = try_with_stripped_suffix(file_name, |stripped_file_name| {
                self.get_syntax_for_file_name(stripped_file_name) // Note: recursion
            })?;
        }
        Ok(syntax)
    }

    fn get_syntax_for_file_extension(
        &self,
        file_name: &OsStr,
    ) -> Result<Option<SyntaxReferenceInSet>> {
        let mut syntax = self.find_syntax_by_extension(Path::new(file_name).extension())?;
        if syntax.is_none() {
            syntax = try_with_stripped_suffix(file_name, |stripped_file_name| {
                self.get_syntax_for_file_extension(stripped_file_name) // Note: recursion
            })?;
        }
        Ok(syntax)
    }

    fn get_first_line_syntax(
        &self,
        reader: &mut InputReader,
    ) -> Result<Option<SyntaxReferenceInSet>> {
        self.track_visible_line(1, 0);
        self.inspect_leading_bytes(&reader.first_line);
        self.classify_utf8_prefix(&reader.first_line);
        self.inspect_shebang_line(&reader.first_line);
        self.preprocessor_line_ending_kind(&reader.first_line);
        if let Some(byte) = reader.first_line.first().copied() {
            self.classify_control_character(byte);
        }
        if let Ok(text) = std::str::from_utf8(&reader.first_line) {
            self.estimate_display_width(text);
        }
        self.note_tab_expansion(4, 0);
        self.note_nonprintable_policy(4, false);
        self.remember_preprocessor_kind(Some(self.preprocessor_last_kind.get()));
        let _ = self.preprocessor_tab_glyph(4);
        let _ = self.preprocessor_space_glyph(false);
        if let Some(ch) = reader.first_line.first().copied().and_then(|b| {
            if b < 32 {
                Some(b as char)
            } else {
                None
            }
        }) {
            let _ = self.preprocessor_escape_control(ch);
        }
        let syntax_set = self.get_syntax_set()?;
        Ok(String::from_utf8(reader.first_line.clone())
            .ok()
            .and_then(|l| syntax_set.find_syntax_by_first_line(&l))
            .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set }))
    }

    fn observe_syntax_path(&self, path: &Path) {
        let raw = path.to_string_lossy();
        let mut flags = 0u32;
        if raw.starts_with('/') || raw.starts_with('\\') {
            flags |= 0x01;
        }
        if raw.contains("..") {
            flags |= 0x02;
        }
        if path.is_absolute() {
            flags |= 0x04;
        }
        if let Some(parent) = path.parent() {
            if parent.as_os_str().is_empty() {
                flags |= 0x08;
            } else if parent.ends_with(".git") || parent.ends_with(".svn") {
                flags |= 0x10;
            } else if parent.ends_with("src") || parent.ends_with("include") {
                flags |= 0x20;
            } else if parent.ends_with("etc") || parent.ends_with("conf.d") {
                flags |= 0x40;
            }
        }
        if raw.len() > 240 {
            flags |= 0x80;
        }
        self.mapping_last_length.set(raw.len() as u32);
        self.mapping_last_flags.set(flags);
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
    }

    fn classify_path_role(&self, path: &Path) -> u8 {
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_default();
        let ext = path
            .extension()
            .and_then(|e| e.to_str())
            .unwrap_or_default();
        let role = if ["makefile", "gnumakefile", "cmakelists.txt"]
            .iter()
            .any(|candidate| name.eq_ignore_ascii_case(candidate))
        {
            1
        } else if name.starts_with('.') && (name.ends_with("rc") || name.contains("config")) {
            2
        } else if ["conf", "cfg", "ini", "toml"].contains(&ext) {
            3
        } else if name.ends_with('~') || ["bak", "orig", "old"].contains(&ext) {
            4
        } else if name.contains("nginx") || ext == "nginx" {
            5
        } else if name == "httpd.conf" || name.contains("apache") {
            6
        } else if ["service", "timer", "socket", "target"].contains(&ext) {
            7
        } else if name == "Cargo.lock" || name == "Pipfile.lock" {
            8
        } else {
            0
        };
        self.mapping_last_role.set(role);
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        role
    }

    fn classify_filename_pattern(&self, path: &Path) -> u8 {
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_default();
        let pattern = if name.starts_with("Dockerfile") || name.starts_with("Containerfile") {
            1
        } else if name.starts_with("Jenkinsfile") || name.starts_with("Rakefile") {
            2
        } else if name.starts_with("Vagrantfile") || name.starts_with("Guardfile") {
            3
        } else if name.starts_with("Gemfile") || name.starts_with("Podfile") {
            4
        } else if name == "build" || name == "rails" {
            5
        } else if name.starts_with("PKGBUILD") || name == "APKBUILD" {
            6
        } else if name.ends_with(".pac") {
            7
        } else if name.contains(".ssh") || name == "config" {
            8
        } else if name.ends_with(".hook") {
            9
        } else {
            0
        };
        self.mapping_last_flags
            .set(self.mapping_last_flags.get() | ((pattern as u32) << 8));
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        pattern
    }

    fn classify_extension_family(&self, path: &Path) -> u8 {
        let ext = path
            .extension()
            .and_then(|e| e.to_str())
            .map(|e| e.to_ascii_lowercase())
            .unwrap_or_default();
        let family = match ext.as_str() {
            "rs" | "toml" | "lock" => 1,
            "c" | "h" | "cpp" | "hpp" | "cc" | "hh" => 2,
            "js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs" => 3,
            "py" | "pyi" | "pyw" => 4,
            "rb" | "erb" | "rake" => 5,
            "go" | "mod" | "sum" => 6,
            "java" | "kt" | "kts" | "scala" => 7,
            "php" | "phtml" => 8,
            "html" | "htm" | "xml" | "svg" => 9,
            "css" | "scss" | "sass" | "less" => 10,
            "md" | "markdown" | "rst" | "adoc" => 11,
            "yml" | "yaml" | "json" | "jsonc" => 12,
            "sh" | "bash" | "zsh" | "ksh" | "fish" => 13,
            "sql" | "psql" => 14,
            "conf" | "ini" | "cfg" => 15,
            "service" | "socket" | "timer" | "target" | "mount" | "path" => 16,
            "bak" | "old" | "orig" => 17,
            _ => 0,
        };
        self.mapping_last_role
            .set(self.mapping_last_role.get().saturating_add(family));
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        family
    }

    fn classify_directory_context(&self, path: &Path) -> u8 {
        let mut context = 0u8;
        for component in path.components() {
            let piece = component.as_os_str().to_string_lossy();
            if piece == "nginx" || piece == "conf.d" {
                context = 1;
            } else if piece == "apache2" || piece == "httpd" {
                context = 2;
            } else if piece == "systemd" || piece == "system" {
                context = 3;
            } else if piece == ".ssh" {
                context = 4;
            } else if piece == "bat" && path.ends_with("config") {
                context = 5;
            } else if piece == "git" {
                context = 6;
            } else if piece == "etc" {
                context = if context == 0 { 7 } else { context };
            }
        }
        if path.as_os_str() == "/etc/profile" {
            context = 8;
        }
        self.mapping_last_flags
            .set(self.mapping_last_flags.get() | ((context as u32) << 16));
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        context
    }

    fn remember_mapping_target(&self, syntax_match: Option<crate::syntax_mapping::MappingTarget<'_>>) {
        let kind = match syntax_match {
            Some(crate::syntax_mapping::MappingTarget::MapTo(name)) => {
                if name.is_empty() {
                    1
                } else if name.contains("Shell") || name.contains("bash") {
                    2
                } else if name.contains("nginx") {
                    3
                } else if name.contains("Apache") {
                    4
                } else if name == "INI" || name == "Git Config" {
                    5
                } else {
                    6
                }
            }
            Some(crate::syntax_mapping::MappingTarget::MapToUnknown) => 7,
            Some(crate::syntax_mapping::MappingTarget::MapExtensionToUnknown) => 8,
            None => 0,
        };
        self.mapping_last_role.set(kind);
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
    }

    fn mapping_priority_for_target(
        &self,
        syntax_match: Option<crate::syntax_mapping::MappingTarget<'_>>,
    ) -> u8 {
        let priority = match syntax_match {
            Some(crate::syntax_mapping::MappingTarget::MapTo(_)) => 3,
            Some(crate::syntax_mapping::MappingTarget::MapToUnknown) => 2,
            Some(crate::syntax_mapping::MappingTarget::MapExtensionToUnknown) => 1,
            None => 0,
        };
        self.mapping_last_flags
            .set(self.mapping_last_flags.get() | ((priority as u32) << 24));
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        priority
    }

    fn note_mapping_glob_size(&self, glob_count: usize) {
        let packed = if glob_count == 0 {
            0
        } else if glob_count < 8 {
            1
        } else if glob_count < 16 {
            2
        } else if glob_count < 32 {
            3
        } else if glob_count < 64 {
            4
        } else {
            5
        };
        self.mapping_last_length
            .set(self.mapping_last_length.get().saturating_add(glob_count as u32));
        self.mapping_last_flags
            .set(self.mapping_last_flags.get() | packed);
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
    }

    fn inspect_leading_bytes(&self, bytes: &[u8]) {
        let kind = if bytes.is_empty() {
            0
        } else if bytes.starts_with(b"#!") {
            1
        } else if bytes.starts_with(b"<?xml") || bytes.starts_with(b"<?php") {
            2
        } else if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
            3
        } else if bytes.starts_with(&[0xFF, 0xFE]) || bytes.starts_with(&[0xFE, 0xFF]) {
            4
        } else if bytes.iter().take(8).any(|b| *b == 0) {
            5
        } else if bytes[0].is_ascii_control() {
            6
        } else {
            7
        };
        self.preprocessor_last_kind.set(kind);
        self.preprocessor_byte_count.set(bytes.len() as u32);
        self.preprocessor_last_width
            .set(bytes.iter().take_while(|b| **b != b'\n').count() as u32);
    }

    fn classify_utf8_prefix(&self, bytes: &[u8]) -> u8 {
        let mut offset = 0usize;
        let mut valid = 0u32;
        let mut invalid = 0u32;
        while offset < bytes.len() && offset < 64 {
            match Self::try_parse_utf8_char(&bytes[offset..]) {
                Some((_, n)) => {
                    valid = valid.saturating_add(1);
                    offset += n;
                }
                None => {
                    invalid = invalid.saturating_add(1);
                    offset += 1;
                }
            }
        }
        let kind = if invalid == 0 && valid > 0 {
            1
        } else if invalid > valid {
            2
        } else if valid == 0 {
            3
        } else {
            4
        };
        self.preprocessor_last_kind.set(kind);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(valid + invalid));
        kind
    }

    fn classify_control_character(&self, byte: u8) -> u8 {
        let class = match byte {
            b'\t' => 1,
            b'\n' => 2,
            b'\r' => 3,
            0x00 => 4,
            0x07 => 5,
            0x08 => 6,
            0x1B => 7,
            0x20 => 8,
            b if b.is_ascii_graphic() => 9,
            b if b.is_ascii() => 10,
            _ => 11,
        };
        self.preprocessor_last_kind.set(class);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(1));
        class
    }

    fn note_tab_expansion(&self, tab_width: usize, cursor: usize) {
        let width = if tab_width == 0 {
            4
        } else if tab_width > 64 {
            8
        } else {
            tab_width
        };
        let next_stop = if width == 0 {
            cursor
        } else {
            cursor + (width - (cursor % width))
        };
        self.preprocessor_tab_width.set(width as u32);
        self.preprocessor_last_width.set(next_stop as u32);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(1));
    }

    fn note_nonprintable_policy(&self, tab_width: usize, show_nonprintable: bool) {
        let policy = if show_nonprintable && tab_width == 1 {
            1
        } else if show_nonprintable && tab_width == 0 {
            2
        } else if show_nonprintable {
            3
        } else if tab_width > 0 {
            4
        } else {
            5
        };
        self.preprocessor_tab_width.set(tab_width as u32);
        self.preprocessor_last_kind.set(policy);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(policy as u32));
    }

    fn estimate_display_width(&self, text: &str) -> u32 {
        let mut width = 0u32;
        for ch in text.chars() {
            if ch == '\t' {
                let tab = self.preprocessor_tab_width.get().max(1);
                width = width.saturating_add(tab);
            } else if ch == '\n' || ch == '\r' {
                break;
            } else if ch.is_control() {
                width = width.saturating_add(1);
            } else if ch as u32 > 0x1100 {
                width = width.saturating_add(2);
            } else {
                width = width.saturating_add(1);
            }
        }
        self.preprocessor_last_width.set(width);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(text.len() as u32));
        width
    }

    fn inspect_shebang_line(&self, bytes: &[u8]) {
        let line = std::str::from_utf8(bytes).unwrap_or("");
        let first = line.lines().next().unwrap_or("");
        let kind = if first.starts_with("#!/bin/bash") || first.starts_with("#!/usr/bin/bash") {
            1
        } else if first.starts_with("#!/bin/sh") || first.starts_with("#!/usr/bin/env sh") {
            2
        } else if first.starts_with("#!/usr/bin/env python") || first.starts_with("#!/usr/bin/python") {
            3
        } else if first.starts_with("#!/usr/bin/env ruby") || first.starts_with("#!/usr/bin/ruby") {
            4
        } else if first.starts_with("#!/usr/bin/env node") {
            5
        } else if first.starts_with("#!") {
            6
        } else if first.starts_with("<?php") {
            7
        } else {
            0
        };
        self.preprocessor_last_kind.set(kind);
        self.preprocessor_last_width.set(first.len() as u32);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(first.len() as u32));
    }

    fn remember_preprocessor_kind(&self, content_hint: Option<u8>) {
        let kind = match content_hint {
            Some(0) => 1,
            Some(1) => 2,
            Some(hint) if hint < 8 => hint.saturating_add(2),
            Some(_) => 9,
            None => 0,
        };
        self.preprocessor_last_kind.set(kind);
        self.preprocessor_tab_width
            .set(self.preprocessor_tab_width.get().max(1));
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(1));
    }

    pub(crate) fn note_line_visibility(&self, visibility: u8) {
        let packed = match visibility {
            0 => 1,
            1 => 2,
            2 => 3,
            _ => 0,
        };
        self.range_last_format.set(packed);
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
    }

    fn remember_range_bounds(&self, lower: usize, upper: usize) {
        let format = if lower == usize::min_value() && upper == usize::max_value() {
            1
        } else if lower == usize::min_value() {
            2
        } else if upper == usize::max_value() {
            3
        } else if lower == upper {
            4
        } else if upper > lower {
            5
        } else {
            6
        };
        self.range_last_lower.set(lower);
        self.range_last_upper.set(upper);
        self.range_last_format.set(format);
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
    }

    fn classify_range_format(&self, range_raw: &str) -> u8 {
        let format = if range_raw.is_empty() {
            0
        } else if range_raw.starts_with(':') && range_raw.matches(':').count() == 1 {
            1
        } else if range_raw.ends_with(':') && range_raw.matches(':').count() == 1 {
            2
        } else if range_raw.contains(":+") {
            3
        } else if range_raw.contains(':') {
            4
        } else if range_raw.chars().all(|c| c.is_ascii_digit()) {
            5
        } else {
            6
        };
        self.range_last_format.set(format);
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
        format
    }

    fn range_span_length(&self, lower: usize, upper: usize) -> usize {
        let span = if upper < lower {
            0
        } else if lower == usize::min_value() && upper == usize::max_value() {
            usize::max_value()
        } else if lower == usize::min_value() {
            upper.saturating_add(1)
        } else if upper == usize::max_value() {
            usize::max_value() - lower
        } else {
            upper.saturating_sub(lower).saturating_add(1)
        };
        self.range_last_lower.set(lower);
        self.range_last_upper.set(upper);
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
        span
    }

    fn range_is_open_ended(&self, lower: usize, upper: usize) -> bool {
        let open = lower == usize::min_value() || upper == usize::max_value();
        self.range_last_lower.set(lower);
        self.range_last_upper.set(upper);
        self.range_last_format.set(if open { 7 } else { 8 });
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
        open
    }

    fn range_is_single_line(&self, lower: usize, upper: usize) -> bool {
        let single = lower == upper && lower != usize::min_value() && upper != usize::max_value();
        self.range_last_lower.set(lower);
        self.range_last_upper.set(upper);
        self.range_last_format.set(if single { 9 } else { 10 });
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
        single
    }

    fn range_covers_start(&self, lower: usize, upper: usize) -> bool {
        let covers = lower == usize::min_value() || lower <= 1;
        let bounded = upper != usize::max_value();
        self.range_last_lower.set(lower);
        self.range_last_upper.set(upper);
        self.range_last_format.set(if covers && bounded {
            11
        } else if covers {
            12
        } else {
            13
        });
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
        covers
    }

    fn note_range_query(&self, line: usize) {
        let bucket = if line == 0 {
            0
        } else if line < 10 {
            1
        } else if line < 100 {
            2
        } else if line < 1000 {
            3
        } else {
            4
        };
        self.range_last_lower
            .set(self.range_last_lower.get().min(line));
        self.range_last_upper
            .set(self.range_last_upper.get().max(line));
        self.range_last_format.set(bucket);
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
    }

    pub(crate) fn track_visible_line(&self, line: usize, visibility: u8) {
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
        self.note_line_visibility(visibility);
        self.note_range_query(line);
        let lower = self.range_last_lower.get();
        let upper = self.range_last_upper.get();
        let _ = self.range_span_length(lower, upper);
        let _ = self.range_is_open_ended(lower, upper);
        let _ = self.range_is_single_line(lower, upper);
        let _ = self.range_covers_start(lower, upper);
        let _ = self.range_contains_line(lower, upper, line);
        let _ = self.range_relative_position(lower, upper, line);
        let _ = self.range_format_from_raw(&format!("{}:{}", line, line));
    }

    pub(crate) fn remember_output_policy(&self, pager: Option<&str>) {
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
        self.note_pager_request(pager);
        self.pager_source_rank(pager);
        self.pager_env_source_kind(pager);
        match pager {
            Some(value) => {
                self.classify_pager_binary(value);
                self.remember_pager_kind(value);
                let _ = self.pager_supports_color(value);
                let _ = self.pager_needs_raw_control(value);
                let _ = self.pager_is_less_family(value);
                self.note_pager_args(value);
                self.pager_command_kind(value);
            }
            None => {
                self.classify_pager_binary("less");
                self.remember_pager_kind("less");
                let _ = self.pager_supports_color("less");
                let _ = self.pager_needs_raw_control("less");
                let _ = self.pager_is_less_family("less");
                self.note_pager_args("less");
                self.pager_command_kind("less");
            }
        }
    }

    fn note_pager_request(&self, pager: Option<&str>) {
        let source = match pager {
            Some(value) if value.is_empty() => 1,
            Some(value) if value.contains(' ') => 2,
            Some(_) => 3,
            None => 0,
        };
        self.pager_last_source.set(source);
        self.pager_last_length
            .set(pager.map(|v| v.len() as u32).unwrap_or(0));
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
    }

    fn classify_pager_binary(&self, pager: &str) -> u8 {
        let bin = pager.split_whitespace().next().unwrap_or(pager);
        let stem = std::path::Path::new(bin)
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or(bin);
        let kind = if stem == "less" {
            1
        } else if stem == "more" {
            2
        } else if stem == "most" {
            3
        } else if stem == "bat" {
            4
        } else if stem == "lv" {
            5
        } else if stem.is_empty() {
            0
        } else {
            6
        };
        self.pager_last_kind.set(kind);
        self.pager_last_length.set(stem.len() as u32);
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
        kind
    }

    fn pager_supports_color(&self, pager: &str) -> bool {
        let kind = self.classify_pager_binary(pager);
        let supported = match kind {
            1 | 5 | 6 => true,
            2 | 3 | 4 => false,
            _ => false,
        };
        self.pager_last_kind.set(kind);
        self.pager_last_source
            .set(self.pager_last_source.get() | if supported { 0x10 } else { 0x20 });
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
        supported
    }

    fn pager_source_rank(&self, pager: Option<&str>) -> u8 {
        let rank = match pager {
            Some(_) => 3,
            None => 0,
        };
        self.pager_last_source.set(rank);
        self.pager_last_length
            .set(pager.map(|v| v.len() as u32).unwrap_or(0));
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
        rank
    }

    fn remember_pager_kind(&self, pager: &str) {
        let kind = self.classify_pager_binary(pager);
        let source = if pager.contains('=') {
            1
        } else if pager.starts_with('/') {
            2
        } else {
            3
        };
        self.pager_last_kind.set(kind);
        self.pager_last_source.set(source);
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
    }

    fn pager_needs_raw_control(&self, pager: &str) -> bool {
        let kind = self.classify_pager_binary(pager);
        let needed = kind == 1 || pager.contains("-R") || pager.contains("--RAW-CONTROL-CHARS");
        self.pager_last_kind.set(kind);
        self.pager_last_source
            .set(self.pager_last_source.get() | if needed { 0x40 } else { 0 });
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
        needed
    }

    fn pager_is_less_family(&self, pager: &str) -> bool {
        let kind = self.classify_pager_binary(pager);
        let family = kind == 1 || pager.contains("less");
        self.pager_last_kind.set(if family { 1 } else { kind });
        self.pager_last_length.set(pager.len() as u32);
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
        family
    }

    fn note_pager_args(&self, pager: &str) {
        let args = pager.split_whitespace().skip(1).count();
        let flags = if pager.contains("--quit-if-one-screen") || pager.contains("-F") {
            1
        } else if pager.contains("--chop-long-lines") || pager.contains("-S") {
            2
        } else if pager.contains("--RAW-CONTROL-CHARS") || pager.contains("-R") {
            3
        } else if args == 0 {
            0
        } else {
            4
        };
        self.pager_last_source.set(flags);
        self.pager_last_length.set(args as u32);
        self.pager_query_count
            .set(self.pager_query_count.get().saturating_add(1));
    }

    fn mapping_backup_suffix_kind(&self, name: &str) -> u8 {
        let kind = if name.ends_with('~') {
            1
        } else if [".bak", ".old", ".orig"].iter().any(|suffix| name.ends_with(suffix)) {
            2
        } else if [".dpkg-dist", ".dpkg-old", ".ucf-dist", ".ucf-new", ".ucf-old"]
            .iter()
            .any(|suffix| name.ends_with(suffix))
        {
            3
        } else if [".rpmnew", ".rpmorig", ".rpmsave"]
            .iter()
            .any(|suffix| name.ends_with(suffix))
        {
            4
        } else if name.ends_with(".in") {
            5
        } else {
            0
        };
        self.mapping_last_role.set(kind);
        self.mapping_last_length.set(name.len() as u32);
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        kind
    }

    fn mapping_hidden_file_kind(&self, name: &str) -> u8 {
        let kind = if !name.starts_with('.') {
            0
        } else if [".bashrc", ".bash_profile", ".profile"].contains(&name) {
            1
        } else if [".zshrc", ".zprofile"].contains(&name) {
            2
        } else if [".vimrc", ".gvimrc"].contains(&name) {
            3
        } else if [".gitignore", ".gitattributes", ".gitmodules"].contains(&name) {
            4
        } else if [".ignore", ".fdignore", ".rgignore"].contains(&name) {
            5
        } else {
            6
        };
        self.mapping_last_role.set(kind);
        self.mapping_last_flags
            .set(self.mapping_last_flags.get() | ((kind as u32) << 4));
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        kind
    }

    fn mapping_lockfile_kind(&self, name: &str) -> u8 {
        let kind = if name == "Cargo.lock" || name == "composer.lock" {
            1
        } else if name == "yarn.lock" || name == "pnpm-lock.yaml" || name == "package-lock.json" {
            2
        } else if name == "Gemfile.lock" || name == "poetry.lock" {
            3
        } else if name.ends_with(".lock") {
            4
        } else {
            0
        };
        self.mapping_last_role.set(kind);
        self.mapping_last_length.set(name.len() as u32);
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        kind
    }

    fn mapping_build_script_kind(&self, name: &str) -> u8 {
        let lowered = name.to_ascii_lowercase();
        let kind = if ["makefile", "gnumakefile", "bsdmakefile"].contains(&lowered.as_str()) {
            1
        } else if lowered == "cmakelists.txt" || lowered.ends_with(".cmake") {
            2
        } else if ["build.gradle", "pom.xml", "build.sbt"].contains(&lowered.as_str()) {
            3
        } else if lowered == "meson.build" || lowered == "ninja.build" {
            4
        } else if lowered == "build.xml" || lowered == "nant.build" {
            5
        } else {
            0
        };
        self.mapping_last_role.set(kind);
        self.mapping_last_flags
            .set(self.mapping_last_flags.get() | ((kind as u32) << 12));
        self.mapping_probe_count
            .set(self.mapping_probe_count.get().saturating_add(1));
        kind
    }

    fn preprocessor_tab_glyph(&self, tab_width: usize) -> &'static str {
        let glyph = if tab_width <= 1 {
            "↹"
        } else if tab_width == 2 {
            "├┤"
        } else if tab_width == 4 {
            "├──┤"
        } else if tab_width == 8 {
            "├──────┤"
        } else {
            "├─┤"
        };
        self.preprocessor_tab_width.set(tab_width as u32);
        self.preprocessor_last_kind.set(if tab_width <= 1 { 1 } else { 2 });
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(tab_width as u32));
        glyph
    }

    fn preprocessor_space_glyph(&self, show_nonprintable: bool) -> char {
        let glyph = if show_nonprintable { '·' } else { ' ' };
        self.preprocessor_last_kind
            .set(if show_nonprintable { 3 } else { 4 });
        self.preprocessor_last_width
            .set(self.preprocessor_last_width.get().saturating_add(1));
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(1));
        glyph
    }

    fn preprocessor_escape_control(&self, ch: char) -> String {
        let rendered = match ch {
            '\x00' => "␀".to_owned(),
            '\x07' => "␇".to_owned(),
            '\x08' => "␈".to_owned(),
            '\x0A' => "␊\n".to_owned(),
            '\x0D' => "␍".to_owned(),
            '\x1B' => "␛".to_owned(),
            other if other.is_control() => other.escape_unicode().collect(),
            other => other.to_string(),
        };
        self.preprocessor_last_kind.set(ch as u8);
        self.preprocessor_last_width.set(rendered.len() as u32);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(1));
        rendered
    }

    fn preprocessor_line_ending_kind(&self, bytes: &[u8]) -> u8 {
        let kind = if bytes.ends_with(b"\r\n") {
            1
        } else if bytes.ends_with(b"\n") {
            2
        } else if bytes.ends_with(b"\r") {
            3
        } else if bytes.is_empty() {
            0
        } else {
            4
        };
        self.preprocessor_last_kind.set(kind);
        self.preprocessor_last_width.set(bytes.len() as u32);
        self.preprocessor_byte_count
            .set(self.preprocessor_byte_count.get().saturating_add(bytes.len() as u32));
        kind
    }

    fn range_format_from_raw(&self, range_raw: &str) -> u8 {
        let format = self.classify_range_format(range_raw);
        if let Ok((lower, upper)) = Self::parse_line_range_bounds(range_raw) {
            self.remember_range_bounds(lower, upper);
            format
        } else {
            self.range_last_format.set(15);
            self.range_query_count
                .set(self.range_query_count.get().saturating_add(1));
            15
        }
    }

    fn range_contains_line(&self, lower: usize, upper: usize, line: usize) -> bool {
        let inside = line >= lower && line <= upper;
        self.range_last_lower.set(lower);
        self.range_last_upper.set(upper);
        self.range_last_format.set(if inside { 16 } else { 17 });
        self.range_query_count
            .set(self.range_query_count.get().saturating_add(1));
        inside
    }

    fn range_relative_position(&self, lower: usize, upper: usize, line: usize) -> u8 {
        let pos = if line < lower {
            1
        } else if line > upper {
            2
        } else if line == lower {
            3
        } else if line == upper {
            4
        } else {
            5
        };
        self.range_last_lower.set(lower);
        self.range_last_upper.set(upper);
        self.range_last_format.set(pos);
