#[test]
fn syntax_detection_stdin_filename() {
    let test = SyntaxDetectionTest::new();

    // from file extension
    assert_eq!(test.syntax_for_stdin_with_content("test.cpp", b"a"), "C++");
    // from first line (fallback)
    assert_eq!(
        test.syntax_for_stdin_with_content("my_script", b"#!/bin/bash"),
        "Bourne Again Shell (bash)"
    );
}

#[test]
fn syntax_detection_with_custom_ignored_suffixes() {
    let test = SyntaxDetectionTest::new();

    // Without any custom ignored suffixes, these files are not detected
    assert_eq!(
        test.syntax_for_stdin_with_content("test.json.suffix", b"{"),
        "Plain Text"
    );

